import { expect } from 'chai';
import request from 'supertest';

import { getExpressApp } from '../index.ts';

const app = getExpressApp();
const NON_EXISTANT_BLOCK_NUMBER = 999999999999999;

describe('Proof Generation API Tests', function () {
  this.timeout(30000);

  describe('server health', function () {
    it('server healthcheck responds', async function () {
      this.timeout(100);

      const res = await request(app).get('/health-check');

      expect(res).property('status', 200);
    });
  });

  describe('block inclusion', function () {
    it('should include block 1234', async function () {
      const res = await request(app).get('/api/v1/matic/block-included/1234');

      expect(res).property('status', 200);
      expect(res).property('body').property('message', 'success');
      expect(res).property('body').property('headerBlockNumber', '0xea60');
    });

    it('should include amoy block 1234', async function () {
      const res = await request(app).get('/api/v1/amoy/block-included/1234');

      expect(res).property('status', 200);
      expect(res).property('body').property('message', 'success');
      expect(res).property('body').property('headerBlockNumber', '0x9c40');
    });

    it(`should not include (return 404) for block ${NON_EXISTANT_BLOCK_NUMBER}`, async function () {
      const res = await request(app).get(
        `/api/v1/matic/block-included/${NON_EXISTANT_BLOCK_NUMBER}`,
      );

      expect(res).property('status', 404);
      expect(res).property('body').property('error', true);
    });

    it('should return error 400 if given a malformed (float) block number', async function () {
      const res = await request(app).get(
        '/api/v1/matic/block-included/12324.56',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });
  });

  describe('merkle proof generation', function () {
    // FIXME: error in fastMerkleProof controller: Cannot read properties of null (reading 'length')
    it('should return the expected proof result for a known block', async function () {
      const res = await request(app).get(
        '/api/v1/matic/fast-merkle-proof?start=12345&end=12347&number=12346',
      );

      expect(res).property('status', 200);
      expect(res)
        .property('body')
        .property(
          'proof',
          '0xc62218dfcdc47711e777e6036806592cac1e079f55e2f8f30e6b165bf8737d163643be7c8414f4fc0cfebecce5ba6c663dfbcd74359e3847a429c268777342bb',
        );
    });

    it('should return error 400 if given a malformed start block number', async function () {
      const res = await request(app).get(
        '/api/v1/matic/fast-merkle-proof?start=12324.56&end=12347&number=12346',
      );
      expect(res).property('status', 400);
    });

    it('invalid merkle proof generation arguments test - 2', async function () {
      const res = await request(app).get(
        '/api/v1/matic/fast-merkle-proof?start=12345&end=12347&number=12348',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('invalid merkle proof generation arguments test - 3', async function () {
      const res = await request(app).get(
        '/api/v1/matic/fast-merkle-proof?start=12348&end=12347&number=12347',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });
  });

  describe('matic exit payload', function () {
    it('exit payload test', async function () {
      const res = await request(app).get(
        '/api/v1/matic/exit-payload/0x1a7b6aba7e51344474d4fe722a3969e8c7a863c72329210a0dda80d26c4234b4?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef',
      );

      expect(res).property('status', 200);
      expect(res)
        .property('body')
        .property(
          'result',
          '',
        );
    });

    it('exit payload with tokenIndex argument test', async function () {
      const res = await request(app).get(
        '/api/v1/matic/exit-payload/0x1a7b6aba7e51344474d4fe722a3969e8c7a863c72329210a0dda80d26c4234b4?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef&tokenIndex=0',
      );

      expect(res).property('status', 200);
      expect(res)
        .property('body')
        .property(
          'result',
          '',
        );
    });

    it('invalid exit payload arguments test - 1', async function () {
      const res = await request(app).get(
        '/api/v1/matic/exit-payload/272ce652e562677a0db65f95d0c0dc1dd11ef6b2099f09acdaf9b831b51f6804?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('invalid exit payload arguments test - 2', async function () {
      const res = await request(app).get(
        '/api/v1/matic/exit-payload/0x272ce652e562?eventSignature=0xdf252ad1be2c89b69c2b068fc378daa95',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('invalid exit payload arguments test - 3', async function () {
      const res = await request(app).get(
        '/api/v1/matic/exit-payload/0x1a7b6aba7e51344474d4fe722a3969e8c7a863c72329210a0dda80d26c4234b4?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef&tokenIndex=1',
      );

      expect(res).property('status', 404);
      expect(res).property('body').property('error', true);
    });

    it('erc1155 exit payload test', async function () {
      const res = await request(app).get(
        '/api/v1/matic/exit-payload/0x4d4a9ee49a681a97ade92788f2fdce1d1761978ab491c2a10eb6849101cd63fe?eventSignature=0x4a39dc06d4c0dbc64b70af90fd698a233a518aa5d07e595d983b8c0526c8f7fb',
      );

      expect(res).property('status', 200);
      expect(res)
        .property('body')
        .property(
          'result',
          '',
        );
    });

    it('erc721 all exit payloads test', async function () {
      const res = await request(app).get(
        '/api/v1/matic/all-exit-payloads/0xdc3e4c2d41edd8c0a059be22aaa48ee6649f3688456db234b7e382e1cf735b50?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef',
      );

      expect(res).property('status', 200);
      expect(res).property('body').property('result').property('length', 1);
    });
  });

  describe('zkEVM endpoints', function () {
    it('zkEVM mainnet bridge — deposit lookup', async function () {
      const res = await request(app).get(
        '/api/zkevm/mainnet/bridge?net_id=1&deposit_cnt=1',
      );

      expect(res).property('status', 200);
      expect(res.body).to.have.property('deposit');
      expect(res.body.deposit).to.have.property(
        'tx_hash',
        '0xb07cd0b30019c78c0b60e464c7c38a0a8076a355dbe9177205573e86455f31b6',
      );
      expect(res.body.deposit).to.have.property('deposit_cnt', 1);
      expect(res.body.deposit).to.have.property('ready_for_claim', true);
    });

    it('zkEVM mainnet merkle-proof — deposit lookup', async function () {
      const res = await request(app).get(
        '/api/zkevm/mainnet/merkle-proof?net_id=1&deposit_cnt=1',
      );

      expect(res).property('status', 200);
      expect(res.body).to.have.property('proof');
      expect(res.body.proof)
        .to.have.property('merkle_proof')
        .that.is.an('array')
        .with.length.greaterThan(0);
      expect(res.body.proof)
        .to.have.property('rollup_merkle_proof')
        .that.is.an('array');
    });

    it('should error 400 for invalid network on zkEVM bridge', async function () {
      const res = await request(app).get(
        '/api/zkevm/polygon/bridge?net_id=1&deposit_cnt=1',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('should error 400 for non-integer deposit_cnt on zkEVM merkle-proof', async function () {
      const res = await request(app).get(
        '/api/zkevm/mainnet/merkle-proof?net_id=1&deposit_cnt=abc',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });
  });

  describe('invalid network param tests', function () {
    it('should error 400 for `mainnet` on `v1` block-included endpoint', async function () {
      const res = await request(app).get(
        '/api/v1/mainnet/block-included/3000000',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('should error 400 for `testnet` on `v1` fast-merkle-proof endpoint', async function () {
      const res = await request(app).get(
        '/api/v1/testnet/fast-merkle-proof?start=12345&end=12347&number=12346',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('should error 400 for `mum` on `v1` exit-payload endpoint', async function () {
      const res = await request(app).get(
        '/api/v1/mum/exit-payload/0x1a7b6aba7e51344474d4fe722a3969e8c7a863c72329210a0dda80d26c4234b4?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });

    it('should error 400 for `mainnet` on `v1` all-exit-payloads endpoint', async function () {
      const res = await request(app).get(
        '/api/v1/mainnet/all-exit-payloads/0x54f47c891b460369661e22e27eeb4afbbb5dd792c7c8b48cab758892c14ffe85?eventSignature=0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef',
      );

      expect(res).property('status', 400);
      expect(res).property('body').property('error', true);
    });
  });
});
